 * Parse a task file into its tasks.
 * @param {string[]} lines - the input lines.
 * @returns {Map<string, {name: string, command: string, needs: string[], reads: string[], writes: string[]}>} the tasks by name, in declaration order.
 */
export function parse(lines) {
  const tasks = new Map()
  const errors = []

  // First pass: parse all directives
  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1
    const raw = lines[i]
    const text = raw.trim()

    // Skip empty lines and comments
    if (text === '' || text.startsWith('#')) continue

    // Split on whitespace
    const words = text.split(/\s+/u)
    if (words.length === 0) continue

    const directive = words[0]

    if (directive === 'task') {
      if (words.length < 3) {
        errors.push(new ParseError(lineNum, 'expected task <name> <word>...'))
        continue
      }

      const name = words[1]
      if (!isName(name)) {
        errors.push(new ParseError(lineNum, `invalid task name ${name}`))
        continue
      }

      if (tasks.has(name)) {
        errors.push(new ParseError(lineNum, `task ${name} is declared twice`))
        continue
      }

      const command = words.slice(2).join(' ')
      tasks.set(name, {
        name,
        command,
        needs: new Set(),
        reads: new Set(),
        writes: new Set(),
      })
    } else if (ATTACHING.has(directive)) {
      if (words.length < 3) {
        const spec = ATTACHING.get(directive)
        errors.push(new ParseError(lineNum, `expected ${directive} <name> <${spec.word}>...`))
        continue
      }

      const name = words[1]
      const items = words.slice(2)

      // Validate paths (only for reads/writes)
      let hasError = false
      if (directive !== 'needs') {
        for (const item of items) {
          if (!isPath(item)) {
            errors.push(new ParseError(lineNum, `invalid path ${item}`))
            hasError = true
          }
        }
      }
      if (hasError) continue

      // Create placeholder task if needed
      if (!tasks.has(name)) {
        tasks.set(name, {
          name,
          command: null, // null indicates placeholder (not yet declared with 'task')
          needs: new Set(),
          reads: new Set(),
          writes: new Set(),
        })
      }

      const task = tasks.get(name)
      const field = ATTACHING.get(directive).field

      // Add items to the set (deduplicates automatically)
      for (const item of items) {
        task[field].add(item)
      }
    } else {
      errors.push(new ParseError(lineNum, `unknown directive ${directive}`))
    }
  }

  // Report line-numbered errors first (in line order)
  for (const error of errors) {
    throw error
  }

  // Second pass: validate that all referenced tasks are declared
  const undeclaredTasks = [...tasks.entries()]
    .filter(([_, task]) => task.command === null)
    .map(([name, _]) => name)
    .sort()

  if (undeclaredTasks.length > 0) {
    throw new ParseError(0, `unknown task ${undeclaredTasks[0]}`)
  }

  // Convert sets to sorted arrays
  const result = new Map()
  for (const [name, task] of tasks) {
    result.set(name, {
      name,
      command: task.command,
      needs: [...task.needs].sort(),
      reads: [...task.reads].sort(),
      writes: [...task.writes].sort(),
    })
  }

  return result
}"}

