const NAME = /^[A-Za-z0-9_.-]+$/;
const PATH = /^[A-Za-z0-9_./-]+$/;
const ATTACHING = new Map([
  ['needs', { field: 'needs', word: 'dependency' }],
  ['reads', { field: 'reads', word: 'path' }],
  ['writes', { field: 'writes', word: 'path' }],
]);

function isName(word) { return NAME.test(word); }
function isPath(word) { return PATH.test(word) && !word.startsWith('/') && !word.split('/').includes('..'); }

class ParseError extends Error {
  constructor(line, message) {
    super(message);
    this.name = 'ParseError';
    this.line = line;
  }
}

function splitLines(text) {
  const split = text.split('\\n');
  if (split.length > 0 && split[split.length - 1] === '') split.pop();
  return split;
}

function parse(lines) {
  const tasks = new Map();
  const errors = [];

  for (let i = 0; i < lines.length; i++) {
    const lineNum = i + 1;
    const raw = lines[i];
    const text = raw.trim();

    if (text === '' || text.startsWith('#')) continue;

    const words = text.split(/\s+/u);
    if (words.length === 0) continue;

    const directive = words[0];

    if (directive === 'task') {
      if (words.length < 3) {
        errors.push(new ParseError(lineNum, 'expected task <name> <word>...'));
        continue;
      }

      const name = words[1];
      if (!isName(name)) {
        errors.push(new ParseError(lineNum, \`invalid task name \${name}\`));
        continue;
      }

      if (tasks.has(name) && tasks.get(name).command !== null) {
        errors.push(new ParseError(lineNum, \`task \${name} is declared twice\`));
        continue;
      }

      const command = words.slice(2).join(' ');
      const existing = tasks.get(name);
      tasks.set(name, {
        name,
        command,
        needs: existing ? existing.needs : new Set(),
        reads: existing ? existing.reads : new Set(),
        writes: existing ? existing.writes : new Set(),
      });
    } else if (ATTACHING.has(directive)) {
      if (words.length < 3) {
        const spec = ATTACHING.get(directive);
        errors.push(new ParseError(lineNum, \`expected \${directive} <name> <\${spec.word}>...\`));
        continue;
      }

      const name = words[1];
      const items = words.slice(2);

      let hasError = false;
      if (directive !== 'needs') {
        for (const item of items) {
          if (!isPath(item)) {
            errors.push(new ParseError(lineNum, \`invalid path \${item}\`));
            hasError = true;
          }
        }
      }
      if (hasError) continue;

      if (!tasks.has(name)) {
        tasks.set(name, {
          name,
          command: null,
          needs: new Set(),
          reads: new Set(),
          writes: new Set(),
        });
      }

      const task = tasks.get(name);
      const field = ATTACHING.get(directive).field;

      for (const item of items) {
        task[field].add(item);
      }
    } else {
      errors.push(new ParseError(lineNum, \`unknown directive \${directive}\`));
    }
  }

  console.log('Tasks before validation:', [...tasks.keys()]);
  for (const [name, task] of tasks) {
    console.log('  ' + name + ': command=' + task.command);
  }

  for (const error of errors) {
    throw error;
  }

  const undeclaredTasks = [...tasks.entries()]
    .filter(([_, task]) => task.command === null)
    .map(([name, _]) => name)
    .sort();

  console.log('Undeclared tasks:', undeclaredTasks);

  if (undeclaredTasks.length > 0) {
    throw new ParseError(0, \`unknown task \${undeclaredTasks[0]}\`);
  }

  const result = new Map();
  for (const [name, task] of tasks) {
    result.set(name, {
      name,
      command: task.command,
      needs: [...task.needs].sort(),
      reads: [...task.reads].sort(),
      writes: [...task.writes].sort(),
    });
  }

  return result;
}

const input = 'task a echo a\nneeds a ghost';
try {
  const result = parse(splitLines(input));
  console.log('Parse succeeded. Tasks:', Array.from(result.keys()));
} catch (e) {
  if (e.name === 'ParseError') {
    console.log('ParseError:', e.message, '(line:', e.line, ')');
  } else {
    console.log('Error:', e.message);
  }
}
